// Unifica las dos entradas en una misma forma. No guarda datos personales: solo qué falló y dónde
// (si un mensaje de error trae un mail, se tapa).
const corto = (v, n = 300) => String(v ?? '').replace(/[^\s@<>"'()]+@[^\s@<>"'()]+/g, '[email]').slice(0, n);

// Texto de la alerta para Telegram (modo HTML: se escapan <, > y &; con Markdown, un "_" como el de
// "aviso_contratacion" hacía que Telegram rechazara el mensaje).
const html = v => String(v ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const alerta = r => ({ ...r, texto_alerta: `ALERTA (referidos): ${html(r.workflow)} falló en "${html(r.nodo)}"\n`
  + `${html(r.mensaje)}\n\nEjecución: ${html(r.execution_url ?? 'sin link')}` });

// Entrada 1: Error Trigger -> { execution: { id, url, error, lastNodeExecuted }, workflow: { id, name } }
if ($json.execution) {
  const e = $json.execution;
  return { json: alerta({
    gravedad: 'critico',
    workflow: corto($json.workflow?.name, 100),
    nodo: corto(e.lastNodeExecuted, 100),
    mensaje: corto(e.error?.message ?? 'Error sin mensaje'),
    execution_id: corto(e.id, 50),
    execution_url: e.url ?? null,
  }) };
}

// Entrada 2: webhook de reportes -> el cuerpo viene en $json.body
const b = $json.body ?? {};
const url = b.workflow_id && b.execution_id
  ? `http://localhost:5678/workflow/${b.workflow_id}/executions/${b.execution_id}`
  : null;
return { json: alerta({
  gravedad: b.gravedad === 'aviso' ? 'aviso' : 'critico',
  workflow: corto(b.workflow, 100),
  nodo: corto(b.nodo, 100),
  mensaje: corto(b.mensaje || 'Sin mensaje'),
  execution_id: corto(b.execution_id, 50),
  execution_url: url,
}) };

// Una sola alerta por problema: durante un corte de conexión, el procesador falla cada minuto con el mismo error.
// Si la misma falla (workflow, nodo y mensaje) ya se avisó dentro de la ventana, no se repite. El registro en la
// tabla `errores` sigue siendo uno por falla. Dos tareas distintas avisan cada una: su mensaje trae el número.
// avisadas = { clave: momento del último aviso (ms) }; en n8n son los datos estáticos del workflow.
// n8n los guarda al terminar cada ejecución: dos fallas idénticas en el mismo instante avisan las dos (probado
// el 22/10). En un corte no pasa, porque el procesador falla una vez por minuto.
const VENTANA_ALERTA_MIN = 30;

function filtrarRepetidas(alertas, avisadas, ahora) {
  const ventana = VENTANA_ALERTA_MIN * 60 * 1000;
  const salen = [];
  for (const a of alertas) {
    const clave = `${a.workflow}|${a.nodo}|${a.mensaje}`;
    if (avisadas[clave] !== undefined && ahora - avisadas[clave] < ventana) continue;
    avisadas[clave] = ahora;
    salen.push({ ...a, texto_alerta: `${a.texto_alerta}\n\n(Si se repite, no vuelvo a avisar por ${VENTANA_ALERTA_MIN} minutos.)` });
  }
  // Se olvidan las claves vencidas para que los datos guardados no crezcan.
  for (const [clave, momento] of Object.entries(avisadas)) {
    if (ahora - momento >= ventana) delete avisadas[clave];
  }
  return salen;
}

// Los datos estáticos del workflow persisten entre ejecuciones de producción (no en las manuales).
const avisadas = $getWorkflowStaticData('global');
return filtrarRepetidas($input.all().map(i => i.json), avisadas, Date.now()).map(json => ({ json }));
